  });

  // AC: @batch-exec ac-stdin — stdin tested via parseBatchInput in batch-schema.test.ts
  // AC: @batch-exec ac-inline
  // AC: @trait-semantic-exit-codes ac-1 — success exits with code 0
  it("accepts inline JSON commands", () => {
